//! Signed update check (architecture §13, task 2.12).
//!
//! Flow: ask the GitHub Releases API for the latest release → compare versions → pick the asset
//! for this platform → (later) download it and verify its minisign signature before it is
//! applied on restart. Updates are never installed unless the signature verifies against
//! [`UPDATE_PUBLIC_KEY`]. While that key is empty the updater is disabled: the release signing
//! key must be generated by the maintainer (`minisign -G`) and kept OUT of the repository;
//! only the public key goes here.

use minisign_verify::{PublicKey, Signature};
use serde::Deserialize;

/// Base64 minisign public key of the release signing key. Empty = updater disabled.
pub const UPDATE_PUBLIC_KEY: &str = "";

pub const RELEASES_API: &str =
    "https://api.github.com/repos/emreyigit-tasdelen/Kendime-Brow/releases/latest";

pub const CURRENT_VERSION: &str = env!("CARGO_PKG_VERSION");

/// Parses `1.2.3` / `v1.2.3` (pre-release suffixes after `-` are ignored for ordering).
pub fn parse_version(v: &str) -> Option<(u64, u64, u64)> {
    let core = v.trim().trim_start_matches('v').split(['-', '+']).next()?;
    let mut it = core.split('.');
    let major = it.next()?.parse().ok()?;
    let minor = it.next().unwrap_or("0").parse().ok()?;
    let patch = it.next().unwrap_or("0").parse().ok()?;
    if it.next().is_some() {
        return None;
    }
    Some((major, minor, patch))
}

pub fn is_newer(candidate: &str, current: &str) -> bool {
    match (parse_version(candidate), parse_version(current)) {
        (Some(c), Some(cur)) => c > cur,
        _ => false,
    }
}

#[derive(Debug, Deserialize)]
pub struct Release {
    pub tag_name: String,
    #[serde(default)]
    pub prerelease: bool,
    #[serde(default)]
    pub assets: Vec<Asset>,
}

#[derive(Debug, Deserialize, Clone, PartialEq, Eq)]
pub struct Asset {
    pub name: String,
    pub browser_download_url: String,
}

/// Asset name suffix for this platform.
pub fn platform_suffix() -> &'static str {
    if cfg!(windows) {
        "-windows-x64.zip"
    } else if cfg!(target_os = "macos") {
        "-macos.dmg"
    } else {
        ".AppImage"
    }
}

/// The package asset and its detached signature (`<asset>.minisig`) for this platform.
pub fn pick_assets(release: &Release) -> Option<(&Asset, &Asset)> {
    let pkg = release
        .assets
        .iter()
        .find(|a| a.name.ends_with(platform_suffix()))?;
    let sig = release
        .assets
        .iter()
        .find(|a| a.name == format!("{}.minisig", pkg.name))?;
    Some((pkg, sig))
}

#[derive(Debug, PartialEq, Eq)]
pub enum VerifyError {
    NoKey,
    BadKey,
    BadSignature,
}

/// Verifies `data` against a minisign signature text with the given base64 public key.
pub fn verify(public_key_b64: &str, signature_text: &str, data: &[u8]) -> Result<(), VerifyError> {
    if public_key_b64.is_empty() {
        return Err(VerifyError::NoKey);
    }
    let key = PublicKey::from_base64(public_key_b64).map_err(|_| VerifyError::BadKey)?;
    let sig = Signature::decode(signature_text).map_err(|_| VerifyError::BadSignature)?;
    key.verify(data, &sig, false)
        .map_err(|_| VerifyError::BadSignature)
}

#[derive(Debug, PartialEq, Eq)]
pub enum Check {
    Disabled,
    UpToDate,
    Available {
        version: String,
        url: String,
        sig_url: String,
    },
    Error(String),
}

/// Network check (blocking; run on a background thread). Never installs anything.
pub fn check_for_update() -> Check {
    if UPDATE_PUBLIC_KEY.is_empty() {
        return Check::Disabled;
    }
    let agent: ureq::Agent = ureq::Agent::config_builder()
        .timeout_global(Some(std::time::Duration::from_secs(20)))
        .user_agent("Kendime-Brow updater")
        .build()
        .into();
    let release: Release = match agent
        .get(RELEASES_API)
        .call()
        .map_err(|e| e.to_string())
        .and_then(|mut r| r.body_mut().read_to_string().map_err(|e| e.to_string()))
        .and_then(|t| serde_json::from_str(&t).map_err(|e| e.to_string()))
    {
        Ok(r) => r,
        Err(e) => return Check::Error(e),
    };
    if release.prerelease || !is_newer(&release.tag_name, CURRENT_VERSION) {
        return Check::UpToDate;
    }
    match pick_assets(&release) {
        Some((pkg, sig)) => Check::Available {
            version: release.tag_name.trim_start_matches('v').to_string(),
            url: pkg.browser_download_url.clone(),
            sig_url: sig.browser_download_url.clone(),
        },
        None => Check::UpToDate,
    }
}

/// Writes `data` to `<dir>/<name>` only if its minisign signature is valid for `key`.
/// Never overwrites an existing file and never runs the package.
pub fn store_verified(
    key: &str,
    dir: &std::path::Path,
    name: &str,
    data: &[u8],
    signature_text: &str,
) -> Result<std::path::PathBuf, String> {
    if name.is_empty() || name.contains(['/', '\\']) || name.starts_with('.') {
        return Err("bad file name".into());
    }
    verify(key, signature_text, data).map_err(|e| format!("signature check failed: {e:?}"))?;
    std::fs::create_dir_all(dir).map_err(|e| e.to_string())?;
    let path = dir.join(name);
    let mut f = std::fs::OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(&path)
        .map_err(|e| e.to_string())?;
    std::io::Write::write_all(&mut f, data).map_err(|e| e.to_string())?;
    Ok(path)
}

/// Downloads an update package and its signature (blocking), checks the signature against
/// `UPDATE_PUBLIC_KEY` and stores the package in `dir`. The package is not executed.
pub fn download_verified(
    url: &str,
    sig_url: &str,
    name: &str,
    dir: &std::path::Path,
) -> Result<std::path::PathBuf, String> {
    if !url.starts_with("https://") || !sig_url.starts_with("https://") {
        return Err("updates must come over https".into());
    }
    let agent: ureq::Agent = ureq::Agent::config_builder()
        .timeout_global(Some(std::time::Duration::from_secs(600)))
        .user_agent("Kendime-Brow updater")
        .build()
        .into();
    let sig = agent
        .get(sig_url)
        .call()
        .map_err(|e| e.to_string())?
        .body_mut()
        .read_to_string()
        .map_err(|e| e.to_string())?;
    let data = agent
        .get(url)
        .call()
        .map_err(|e| e.to_string())?
        .body_mut()
        .with_config()
        .limit(1 << 30)
        .read_to_vec()
        .map_err(|e| e.to_string())?;
    store_verified(UPDATE_PUBLIC_KEY, dir, name, &data, &sig)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn versions() {
        assert_eq!(parse_version("v1.2.3"), Some((1, 2, 3)));
        assert_eq!(parse_version("0.9"), Some((0, 9, 0)));
        assert_eq!(parse_version("1.0.0-rc1"), Some((1, 0, 0)));
        assert_eq!(parse_version("1.2.3.4"), None);
        assert_eq!(parse_version("x"), None);
        assert!(is_newer("v0.10.0", "0.9.5"));
        assert!(!is_newer("0.9.5", "0.9.5"));
        assert!(!is_newer("junk", "0.1.0"));
    }

    #[test]
    fn asset_selection() {
        let name = format!("Kendime-Brow-0.2.0{}", platform_suffix());
        let rel = Release {
            tag_name: "v0.2.0".into(),
            prerelease: false,
            assets: vec![
                Asset {
                    name: "notes.txt".into(),
                    browser_download_url: "u0".into(),
                },
                Asset {
                    name: name.clone(),
                    browser_download_url: "u1".into(),
                },
                Asset {
                    name: format!("{name}.minisig"),
                    browser_download_url: "u2".into(),
                },
            ],
        };
        let (pkg, sig) = pick_assets(&rel).unwrap();
        assert_eq!(
            (
                pkg.browser_download_url.as_str(),
                sig.browser_download_url.as_str()
            ),
            ("u1", "u2")
        );
        let unsigned = Release {
            assets: rel.assets[..2].to_vec(),
            ..rel
        };
        assert!(
            pick_assets(&unsigned).is_none(),
            "unsigned releases are never offered"
        );
    }

    /// Test vector from the minisign-verify documentation.
    #[test]
    fn signature_verification() {
        let key = "RWQf6LRCGA9i53mlYecO4IzT51TGPpvWucNSCh1CBM0QTaLn73Y7GFO3";
        let sig = "untrusted comment: signature from minisign secret key\nRUQf6LRCGA9i559r3g7V1qNyJDApGip8MfqcadIgT9CuhV3EMhHoN1mGTkUidF/z7SrlQgXdy8ofjb7bNJJylDOocrCo8KLzZwo=\ntrusted comment: timestamp:1633700835\tfile:test\tprehashed\nwLMDjy9FLAuxZ3q4NlEvkgtyhrr0gtTu6KC4KBJdITbbOeAi1zBIYo0v4iTgt8jJpIidRJnp94ABQkJAgAooBQ==";
        assert_eq!(verify(key, sig, b"test"), Ok(()));
        assert_eq!(
            verify(key, sig, b"tampered"),
            Err(VerifyError::BadSignature)
        );
        assert_eq!(verify("", sig, b"test"), Err(VerifyError::NoKey));
        assert_eq!(verify("not-a-key", sig, b"test"), Err(VerifyError::BadKey));
    }

    #[test]
    fn store_verified_checks_signature_and_name() {
        let key = "RWQf6LRCGA9i53mlYecO4IzT51TGPpvWucNSCh1CBM0QTaLn73Y7GFO3";
        let sig = "untrusted comment: signature from minisign secret key
RUQf6LRCGA9i559r3g7V1qNyJDApGip8MfqcadIgT9CuhV3EMhHoN1mGTkUidF/z7SrlQgXdy8ofjb7bNJJylDOocrCo8KLzZwo=
trusted comment: timestamp:1633700835	file:test	prehashed
wLMDjy9FLAuxZ3q4NlEvkgtyhrr0gtTu6KC4KBJdITbbOeAi1zBIYo0v4iTgt8jJpIidRJnp94ABQkJAgAooBQ==";
        let d = std::env::temp_dir().join(format!("kb-upd-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&d);
        assert!(store_verified(key, &d, "pkg", b"tampered", sig).is_err());
        assert!(!d.join("pkg").exists());
        assert!(store_verified(key, &d, "../pkg", b"test", sig).is_err());
        let p = store_verified(key, &d, "pkg", b"test", sig).unwrap();
        assert_eq!(std::fs::read(&p).unwrap(), b"test");
        assert!(store_verified(key, &d, "pkg", b"test", sig).is_err());
        assert!(download_verified("http://x", "https://y", "p", &d).is_err());
        let _ = std::fs::remove_dir_all(&d);
    }

    #[test]
    fn disabled_without_key() {
        assert_eq!(check_for_update(), Check::Disabled);
    }
}

/// Component downloader (task 3B.2): fetches `url` over https, checks its SHA-256 against
/// `sha256_hex` and stores it as `<dir>/<name>`. Nothing is extracted or executed here, and an
/// existing file is never overwritten.
pub fn download_component(
    url: &str,
    sha256_hex: &str,
    dir: &std::path::Path,
    name: &str,
) -> Result<std::path::PathBuf, String> {
    if !url.starts_with("https://") {
        return Err("components must come over https".into());
    }
    let data = ureq::get(url)
        .call()
        .map_err(|e| e.to_string())?
        .body_mut()
        .with_config()
        .limit(1 << 31)
        .read_to_vec()
        .map_err(|e| e.to_string())?;
    store_checked(dir, name, &data, sha256_hex)
}

pub(crate) fn store_checked(
    dir: &std::path::Path,
    name: &str,
    data: &[u8],
    sha256_hex: &str,
) -> Result<std::path::PathBuf, String> {
    use sha2::{Digest, Sha256};
    if name.is_empty() || name.contains(['/', '\\']) || name.starts_with('.') {
        return Err("bad file name".into());
    }
    let got: String = Sha256::digest(data)
        .iter()
        .map(|b| format!("{b:02x}"))
        .collect();
    if !got.eq_ignore_ascii_case(sha256_hex.trim()) {
        return Err("checksum mismatch".into());
    }
    std::fs::create_dir_all(dir).map_err(|e| e.to_string())?;
    let path = dir.join(name);
    let mut f = std::fs::OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(&path)
        .map_err(|e| e.to_string())?;
    std::io::Write::write_all(&mut f, data).map_err(|e| e.to_string())?;
    Ok(path)
}

#[cfg(test)]
mod component_tests {
    use super::*;

    #[test]
    fn component_checksum_enforced() {
        let d = std::env::temp_dir().join(format!("kb-comp-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&d);
        // sha256("test")
        let h = "9f86d081884c7d659a2feaa0c55ad015a3bf4f1b2b0b822cd15d6c15b0f00a08";
        assert!(store_checked(&d, "c.bin", b"nope", h).is_err());
        assert!(store_checked(&d, "../c", b"test", h).is_err());
        assert!(store_checked(&d, "c.bin", b"test", h).is_ok());
        assert!(store_checked(&d, "c.bin", b"test", h).is_err());
        assert!(download_component("http://x", h, &d, "c").is_err());
        let _ = std::fs::remove_dir_all(&d);
    }
}
